namespace InventoryApp.Models;

public class Equipment
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public DateTime LastInspected { get; set; }
}

using InventoryApp.Models;

namespace InventoryApp.Services;

public class EquipmentService
{
    public async Task<List<Equipment>> GetAllAsync()
    {
        // Simulate a slow data source
        await Task.Delay(500);

        return new List<Equipment>
        {
            new() { Id = 1, Name = "Forklift A",        Location = "Warehouse 1", LastInspected = new DateTime(2026, 6, 15) },
            new() { Id = 2, Name = "Conveyor Belt B",   Location = "Warehouse 2", LastInspected = new DateTime(2026, 5, 22) },
            new() { Id = 3, Name = "Hydraulic Press C",  Location = "Factory Floor", LastInspected = new DateTime(2026, 4, 10) },
            new() { Id = 4, Name = "CNC Lathe D",       Location = "Machine Shop", LastInspected = new DateTime(2026, 7, 1) },
            new() { Id = 5, Name = "Welding Robot E",   Location = "Assembly Line", LastInspected = new DateTime(2026, 3, 30) },
            new() { Id = 6, Name = "Pallet Jack F",     Location = "Warehouse 1", LastInspected = new DateTime(2026, 6, 28) },
            new() { Id = 7, Name = "Air Compressor G",  Location = "Utility Room", LastInspected = new DateTime(2026, 2, 14) },
            new() { Id = 8, Name = "Overhead Crane H",  Location = "Loading Dock", LastInspected = new DateTime(2026, 5, 5) },
        };
    }
}

@page "/inventory"
@rendermode InteractiveServer
@using InventoryApp.Models
@using InventoryApp.Services
@inject EquipmentService EquipmentSvc
@inject PersistentComponentState PersistState
@implements IDisposable

<PageTitle>Inventory</PageTitle>

<h1>Equipment Inventory</h1>

@if (_items is null)
{
    <p><em>Loading inventory...</em></p>
}
else
{
    <table class="table">
        <thead>
            <tr>
                <th>Id</th>
                <th>Name</th>
                <th>Location</th>
                <th>Last Inspected</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var item in _items)
            {
                <tr>
                    <td>@item.Id</td>
                    <td>@item.Name</td>
                    <td>@item.Location</td>
                    <td>@item.LastInspected.ToShortDateString()</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Equipment>? _items;
    private PersistingComponentStateSubscription _subscription;

    protected override async Task OnInitializedAsync()
    {
        // Register a callback so that during prerender, after the component tree
        // is rendered, the framework serialises _items into the HTML payload.
        _subscription = PersistState.RegisterOnPersisting(PersistData);

        // If the interactive circuit is starting up and persisted state exists,
        // use it instead of calling the service again.
        if (PersistState.TryTakeFromJson<List<Equipment>>("inventory", out var restored))
        {
            _items = restored;
        }
        else
        {
            // First render (prerender) — actually call the service.
            _items = await EquipmentSvc.GetAllAsync();
        }
    }

    private Task PersistData()
    {
        PersistState.PersistAsJson("inventory", _items);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

